(()=>{
 const info=document.getElementById('info-panel'),toggle=document.getElementById('customize-toggle'),columns=[...info.querySelectorAll('[data-document]')];
 const defaults=()=>({scale:1,x:0,y:0,size:16,weight:400,leading:1.28,tracking:0,wordSpacing:0,paragraph:1.4,family:'Consolas,monospace',align:innerWidth<650?'left':'justify',color:'#070707'});
 const contents=columns.map(column=>{const content=document.createElement('div');content.className='document-content';while(column.firstChild)content.append(column.firstChild);column.append(content);return content}),originalContent=contents.map(c=>c.innerHTML);
 const globalDefaults={background:'#f9f9f9',gridColor:'#000000',gridOpacity:.15,gridSpacing:innerWidth<600?12:15,tabStroke:2.25},globalNames=new Set(['gap','width',...Object.keys(globalDefaults)]);
 const key='pause-info-layout-v1';let state={columns:[defaults(),defaults()],gap:innerWidth<650?44:80,width:100,...globalDefaults},target='both';
 try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.columns?.length===2)state={...state,...saved,columns:saved.columns.map(c=>({...defaults(),...c}))}}catch{}
 // Migrate the previous default while retaining deliberately customized opacity.
 if(!state.gridRevision){if(state.gridOpacity===.2)state.gridOpacity=.15;state.gridRevision=20}
 function cleanHTML(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','DIV','SPAN','BR','UL','OL','LI','STRONG','B','EM','I','A','TIME']);for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.replaceWith(document.createTextNode(el.textContent));continue}for(const attr of [...el.attributes])if(!['class','href','datetime'].includes(attr.name))el.removeAttribute(attr.name);if(el.hasAttribute('href')&&!/^https:\/\//i.test(el.getAttribute('href')))el.removeAttribute('href')}return doc.body.innerHTML}
 if(state.content?.length===2)contents.forEach((c,i)=>c.innerHTML=cleanHTML(state.content[i]));
 const panel=document.createElement('aside');panel.id='customize-panel';panel.className='customize-panel';panel.hidden=true;panel.setAttribute('aria-label','Info layout customization');panel.innerHTML='<h2>Customize Info</h2><label>Apply to<select id="edit-target" aria-label="Apply to"><option value="both">Both columns</option><option value="0">Left column</option><option value="1">Right column</option></select></label><label class="content-edit-label"><input type="checkbox" id="edit-content">Edit Info text directly</label><div id="customize-fields"></div><div class="customize-actions"><button type="button" id="save-info">Save changes</button><button type="button" id="export-info">Export backup</button><button type="button" id="import-info">Import backup</button><input id="import-file" type="file" accept="application/json" hidden><button type="button" id="reset-layout">Reset all</button><button type="button" id="close-customize">Done</button></div><p class="hint">Drag a column’s Move handle, or use its arrow keys. Edit any Info text directly. Save keeps content and styling in this browser; export creates a portable backup.</p>';document.body.append(panel);const status=document.createElement('output');status.className='save-status';status.setAttribute('aria-live','polite');panel.append(status);
 const definitions=[
 ['scale','Scale','range',.5,1.8,.01],['x','Horizontal position','range',-500,500,1],['y','Vertical position','range',-400,500,1],
 ['size','Font size','range',12,30,1],['family','Font','select',[['Consolas,monospace','Consolas'],['"Courier New",monospace','Courier New'],['Arial,sans-serif','Arial'],['Georgia,serif','Georgia']]],
 ['weight','Font weight','range',100,900,100],['leading','Line height','range',1,2.4,.05],['tracking','Letter spacing','range',-.06,.3,.01],['wordSpacing','Word spacing','range',0,1,.01],['paragraph','Paragraph spacing','range',.4,3,.1],
 ['align','Alignment','select',[['left','Left'],['justify','Justified'],['center','Center'],['right','Right']]],['color','Text color','color'],['background','Page background','color'],['gridColor','Background letters','color'],['gridOpacity','Background opacity','range',0,.5,.01],['gridSpacing','Background grid spacing','range',10,30,1],['tabStroke','Tab line thickness','range',1,4,.25],['gap','Column gap','range',20,180,1],['width','Document width','range',60,100,1]
 ];
 const inputs=new Map(),outputs=new Map(),fields=panel.querySelector('#customize-fields');
 for(const [name,title,type,min,max,step] of definitions){const label=document.createElement('label'),text=document.createElement('span');text.textContent=title;label.append(text);const input=document.createElement(type==='select'?'select':'input');input.id='info-setting-'+name;input.setAttribute('aria-label',title);if(type==='select'){for(const [value,title] of min){const option=document.createElement('option');option.value=value;option.textContent=title;input.append(option)}}else{input.type=type;if(type==='range'){input.min=min;input.max=max;input.step=step;const output=document.createElement('output');output.htmlFor=input.id;text.append(document.createElement('br'),output);outputs.set(name,output)}}label.append(input);fields.append(label);inputs.set(name,input);
 input.addEventListener('input',()=>{const value=type==='range'?Number(input.value):input.value;if(globalNames.has(name))state[name]=value;else for(const index of selected())state.columns[index][name]=value;apply();persist();syncOutputs()})}
 function selected(){return target==='both'?[0,1]:[Number(target)]}
 function persist(){try{state.content=contents.map(c=>c.innerHTML);localStorage.setItem(key,JSON.stringify(state));status.textContent='Saved in this browser.'}catch{status.textContent='Could not save. Export a backup instead.'}}
 function apply(){for(const [name,value] of Object.entries(globalDefaults))document.documentElement.style.setProperty('--site-'+name,state[name]??value);document.dispatchEvent(new Event('site-style-change'));info.style.setProperty('--column-gap',state.gap+'px');info.style.setProperty('--document-width',state.width+'%');columns.forEach((column,index)=>{const c=state.columns[index];const css={'--doc-scale':c.scale,'--doc-x':c.x+'px','--doc-y':c.y+'px','--doc-size':c.size+'px','--doc-family':c.family,'--doc-weight':c.weight,'--doc-leading':c.leading,'--doc-tracking':c.tracking+'em','--doc-word-spacing':c.wordSpacing+'em','--doc-paragraph':c.paragraph+'em','--doc-align':c.align,'--doc-color':c.color};for(const [name,value] of Object.entries(css))column.style.setProperty(name,value);column.classList.toggle('edit-target',selected().includes(index))})}
 function syncOutputs(){const c=state.columns[selected()[0]];for(const [name,output] of outputs){const value=globalNames.has(name)?state[name]:c[name];output.value=name==='scale'?Math.round(value*100)+'%':name==='size'||name==='x'||name==='y'||name==='gap'?value+'px':name==='width'?value+'%':String(value)}}
 function syncControls(){const c=state.columns[selected()[0]];for(const [name,input] of inputs)input.value=globalNames.has(name)?state[name]:c[name];panel.querySelector('#edit-target').value=target;syncOutputs();apply()}
 function open(value){panel.hidden=!value;document.body.classList.toggle('customizing',value);toggle.setAttribute('aria-expanded',String(value));if(!value){contents.forEach(c=>c.contentEditable='false');panel.querySelector('#edit-content').checked=false}else{panel.scrollTop=0;syncControls()}}
 toggle.addEventListener('click',()=>open(panel.hidden));panel.querySelector('#close-customize').addEventListener('click',()=>{persist();open(false);toggle.focus()});panel.querySelector('#edit-target').addEventListener('change',e=>{target=e.target.value;syncControls()});panel.querySelector('#reset-layout').addEventListener('click',()=>{state={columns:[defaults(),defaults()],gap:innerWidth<650?44:80,width:100,...globalDefaults};contents.forEach((c,i)=>c.innerHTML=originalContent[i]);syncControls();persist()});
 panel.querySelector('#edit-content').addEventListener('change',e=>{contents.forEach(c=>c.contentEditable=String(e.target.checked));status.textContent=e.target.checked?'Click any Info text to edit it.':''});
 contents.forEach(content=>{content.addEventListener('input',()=>{status.textContent='Text changed. Click Save changes.'});content.addEventListener('click',e=>{if(content.isContentEditable&&e.target.closest('a'))e.preventDefault()});content.addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))})});
 panel.querySelector('#save-info').addEventListener('click',persist);
 panel.querySelector('#export-info').addEventListener('click',()=>{persist();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='info-customization.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
 panel.querySelector('#import-info').addEventListener('click',()=>panel.querySelector('#import-file').click());
 panel.querySelector('#import-file').addEventListener('change',async e=>{try{const saved=JSON.parse(await e.target.files[0].text());if(saved.columns?.length!==2)throw Error();for(const c of saved.columns)for(const [name,,,min,max] of definitions)if(typeof min==='number'&&name!=='gap'&&name!=='width')c[name]=Math.max(min,Math.min(max,Number(c[name])||defaults()[name]));state={...state,...saved,columns:saved.columns.map(c=>({...defaults(),...c}))};if(state.content?.length===2)contents.forEach((c,i)=>c.innerHTML=cleanHTML(state.content[i]));syncControls();persist()}catch{status.textContent='Choose a valid Info backup.'}e.target.value=''});
 addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){open(false);toggle.focus()}});
 columns.forEach((column,index)=>{const handle=document.createElement('button');handle.className='document-handle';handle.type='button';handle.textContent='Move '+(index===0?'left':'right')+' column';handle.setAttribute('aria-label',handle.textContent);column.prepend(handle);let drag=null;
 handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;target=String(index);syncControls();drag={id:e.pointerId,x:e.clientX,y:e.clientY,ox:state.columns[index].x,oy:state.columns[index].y};handle.setPointerCapture(e.pointerId);e.preventDefault()});handle.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;state.columns[index].x=Math.round(drag.ox+e.clientX-drag.x);state.columns[index].y=Math.round(drag.oy+e.clientY-drag.y);apply();syncControls()});const finish=()=>{if(drag){persist();drag=null}};handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);
 handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const delta=e.shiftKey?10:1;state.columns[index].x+=(e.key==='ArrowRight'?delta:e.key==='ArrowLeft'?-delta:0);state.columns[index].y+=(e.key==='ArrowDown'?delta:e.key==='ArrowUp'?-delta:0);target=String(index);syncControls();persist()})});
 new MutationObserver(()=>{if(info.hidden)open(false)}).observe(info,{attributes:true,attributeFilter:['hidden']});apply();
})();
